<script setup lang="ts">defineProps<{accept?:string;disabled?:boolean;name?:string}>(); const emit=defineEmits<{ 'update:modelValue':[value:File|null] }>(); const input=ref<HTMLInputElement>(); function open(){input.value?.click()} function change(e:Event){emit('update:modelValue',(e.target as HTMLInputElement).files?.[0] || null)}</script>
<template><div><input ref="input" type="file" :name="name" :accept="accept" :disabled="disabled" hidden @change="change"><slot :open="open"><PvButton type="button" :disabled="disabled" @click="open">Choose file</PvButton></slot></div></template>